{% endif %}
{% if s.outreach_text %}
Recommended outreach: {{ s.outreach_text | plain }}
{% endif %}
{% if s.links %}
Sources:
{% for l in s.links %}
  {{ l.label }}: {{ l.url }}
{% endfor %}
{% endif %}

{% endfor %}
{% if priority_actions %}
PRIORITY ACTIONS

{% for a in priority_actions %}
{{ a.company | upper }}
{% if a.why_now %}Why now? {{ a.why_now }}
{% endif %}{% if a.action %}Action: {{ a.action }}
{% endif %}

{% endfor %}
{% endif %}
